def main() -> None:
    data = json.loads(DATA_FILE.read_text(encoding="utf-8"))
    data["meta"]["subtitle_en"] = "Curated Directory of AI Agent Open Source, Skills, MCP Servers, Apps & Tools"

    for i, tr in enumerate(data["trends"]):
        tr["title_en"], tr["summary_en"] = TRENDS_EN[i]

    for cat in data["categories"]:
        cat["summary_en"] = CAT_SUMMARY_EN[cat["id"]]

    missing = []
    for t in data["tools"]:
        if t["name"] in NAME_EN:
            t["name_en"] = NAME_EN[t["name"]]
        if t["subcategory"] not in SUBCAT_EN:
            raise ValueError(f"Missing subcategory_en: {t['subcategory']}")
        t["subcategory_en"] = SUBCAT_EN[t["subcategory"]]
        if t["name"] not in DESC_EN:
            missing.append(t["name"])
        else:
            t["description_en"] = DESC_EN[t["name"]]

    if missing:
        raise ValueError(f"Missing English descriptions for {len(missing)} tools: {missing}")

    DATA_FILE.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print(f"Updated data/tools.json with English translations for all {len(data['tools'])} tools.")


if __name__ == "__main__":
    main()
